package com.example.artsan_finder.data.local

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import com.example.artsan_finder.data.model.User
import kotlinx.coroutines.flow.Flow

@Dao
interface UserDao {
    @Query("SELECT * FROM users WHERE id = :userId")
    fun getUserById(userId: String): Flow<User?>

    @Query("SELECT * FROM users WHERE email = :email LIMIT 1")
    suspend fun getUserByEmail(email: String): User?
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertUser(user: User)

    @Query("DELETE FROM users")
    suspend fun clearUsers()
}

package com.example.artsan_finder.data.local

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import com.example.artsan_finder.data.model.User
import kotlinx.coroutines.flow.Flow

@Dao
interface UserDao {
    @Query("SELECT * FROM users WHERE id = :userId")
    fun getUserById(userId: String): Flow<User?>

    @Query("SELECT * FROM users WHERE email = :email LIMIT 1")
    suspend fun getUserByEmail(email: String): User?
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertUser(user: User)

    @Query("DELETE FROM users")
    suspend fun clearUsers()

    @Query("DELETE FROM users WHERE id = :userId")
    suspend fun deleteUserById(userId: String)
}

package com.example.artsan_finder.data.model

import androidx.room.Entity
import androidx.room.PrimaryKey
import com.squareup.moshi.Json
import com.squareup.moshi.JsonClass

@JsonClass(generateAdapter = true)
@Entity(tableName = "users")
data class User(
    @PrimaryKey
    @Json(name = "id")
    val id: String,
    @Json(name = "email")
    val email: String,
    @Json(name = "name")
    val name: String,
    @Json(name = "role")
    val role: UserRole
)

package com.example.artsan_finder.data.model

import androidx.room.Entity
import androidx.room.PrimaryKey
import com.squareup.moshi.Json
import com.squareup.moshi.JsonClass

@JsonClass(generateAdapter = true)
@Entity(tableName = "users")
data class User(
    @PrimaryKey
    @Json(name = "id")
    val id: String,
    @Json(name = "email")
    val email: String,
    @Json(name = "name")
    val name: String,
    @Json(name = "role")
    val role: UserRole,
    // Optional password stored locally for the mock authentication flow
    @Json(name = "password")
    val password: String? = null
)

package com.example.artsan_finder.data.repository

import android.content.Context
import com.example.artsan_finder.data.local.LocalStorageManager
import com.example.artsan_finder.data.local.UserDao
import com.example.artsan_finder.data.model.User
import com.example.artsan_finder.data.model.UserRole
import kotlinx.coroutines.flow.Flow
import java.util.UUID

class AuthRepository(
    private val context: Context,
    private val userDao: UserDao,
    private val storageManager: LocalStorageManager
) {
    // Return user ID if logged in (regardless of Remember Me preference).
    // Users are logged in immediately after login; Remember Me is a separate preference.
    val currentUserId: Flow<String?> = storageManager.currentUserId

    suspend fun login(email: String, password: String, remember: Boolean = false): Result<User> {
        // Validate credentials against local database; only registered users can login
        if (email.isBlank() || password.isBlank()) {
            return Result.failure(Exception("Invalid email or password"))
        }

        val storedUser = userDao.getUserByEmail(email)
        return if (storedUser != null) {
            // Compare stored password (nullable) with provided password
            if (!storedUser.password.isNullOrEmpty() && storedUser.password == password) {
                // Save to both Room DB and local storage
                userDao.insertUser(storedUser)
                storageManager.saveUserSession(storedUser.id, storedUser.email, storedUser.name, remember)
                Result.success(storedUser)
            } else {
                Result.failure(Exception("Invalid email or password"))
            }
        } else {
            Result.failure(Exception("No account found for that email"))
        }
    }

    suspend fun register(name: String, email: String, password: String): Result<User> {
        val user = User(UUID.randomUUID().toString(), email, name, UserRole.CUSTOMER, password)
        // Create the user in local DB but DO NOT create a session here.
        // We want the user to register first, then explicitly login with credentials.
        userDao.insertUser(user)
        return Result.success(user)
    }

    suspend fun logout() {
        // Only clear the session on logout. Do NOT remove users from the local DB
        // so that users can login again later with the same credentials.
        storageManager.clearUserSession()
    }


    fun getUser(userId: String): Flow<User?> = userDao.getUserById(userId)
}

package com.example.artsan_finder.data.repository

import android.content.Context
import com.example.artsan_finder.data.local.LocalStorageManager
import com.example.artsan_finder.data.local.UserDao
import com.example.artsan_finder.data.model.User
import com.example.artsan_finder.data.model.UserRole
import kotlinx.coroutines.flow.Flow
import java.util.UUID

class AuthRepository(
    private val context: Context,
    private val userDao: UserDao,
    private val storageManager: LocalStorageManager
) {
    // Return user ID if logged in (regardless of Remember Me preference).
    // Users are logged in immediately after login; Remember Me is a separate preference.
    val currentUserId: Flow<String?> = storageManager.currentUserId

    suspend fun login(email: String, password: String, remember: Boolean = false): Result<User> {
        // Validate credentials against local database; only registered users can login
        if (email.isBlank() || password.isBlank()) {
            return Result.failure(Exception("Invalid email or password"))
        }

        val storedUser = userDao.getUserByEmail(email)
        return if (storedUser != null) {
            // Compare stored password (nullable) with provided password
            if (!storedUser.password.isNullOrEmpty() && storedUser.password == password) {
                // Save to both Room DB and local storage
                userDao.insertUser(storedUser)
                storageManager.saveUserSession(storedUser.id, storedUser.email, storedUser.name, remember)
                Result.success(storedUser)
            } else {
                Result.failure(Exception("Invalid email or password"))
            }
        } else {
            Result.failure(Exception("No account found for that email"))
        }
    }

    suspend fun register(name: String, email: String, password: String): Result<User> {
        val user = User(UUID.randomUUID().toString(), email, name, UserRole.CUSTOMER, password)
        // Create the user in local DB but DO NOT create a session here.
        // We want the user to register first, then explicitly login with credentials.
        userDao.insertUser(user)
        return Result.success(user)
    }

    suspend fun logout() {
        // Only clear the session on logout. Do NOT remove users from the local DB
        // so that users can login again later with the same credentials.
        storageManager.clearUserSession()
    }

    suspend fun deleteAccount(userId: String) {
        // Remove user record and clear session
        userDao.deleteUserById(userId)
        storageManager.clearUserSession()
    }

    fun getUser(userId: String): Flow<User?> = userDao.getUserById(userId)
}
